# windowed :: ([1, 2, 3, 4, 5], 2)
def windowed(xs, n):
    if n <= 0 or not xs:
        return []
    return [xs[i:i + n] for i in range(len(xs) - n + 1)]

if __name__ == '__main__':
    print(windowed(([1, 2, 3, 4, 5], 2)))

